/* Simplified Highlight.js for Offline Use */
(function(global){
  var hljs = {
    getLanguage: function(lang) { return lang && this.languages[lang]; },
    languages: {
      javascript: true, js: true, typescript: true, ts: true,
      python: true, py: true, java: true, c: true, cpp: true,
      csharp: true, cs: true, go: true, rust: true, ruby: true,
      php: true, swift: true, kotlin: true, html: true, css: true,
      json: true, xml: true, yaml: true, yml: true, markdown: true,
      md: true, sql: true, bash: true, shell: true, sh: true
    },
    highlight: function(code, opts) {
      return { value: this.highlightAuto(code).value };
    },
    highlightAuto: function(code) {
      var html = code;
      // Keywords
      var keywords = /\b(function|return|if|else|for|while|do|switch|case|break|continue|var|let|const|class|extends|import|export|from|default|new|this|super|try|catch|finally|throw|async|await|yield|static|public|private|protected|interface|implements|enum|type|namespace|module|declare|abstract|readonly|override)\b/g;
      html = html.replace(keywords, '<span class="hljs-keyword">$1</span>');
      // Strings
      html = html.replace(/(["'`])(?:(?!\1)[^\\]|\\.)*\1/g, '<span class="hljs-string">$&</span>');
      // Numbers
      html = html.replace(/\b(\d+\.?\d*)\b/g, '<span class="hljs-number">$1</span>');
      // Comments
      html = html.replace(/(\/\/.*$)/gm, '<span class="hljs-comment">$1</span>');
      html = html.replace(/(\/\*[\s\S]*?\*\/)/g, '<span class="hljs-comment">$1</span>');
      html = html.replace(/(#.*$)/gm, '<span class="hljs-comment">$1</span>');
      // Functions
      html = html.replace(/\b([a-zA-Z_]\w*)\s*\(/g, '<span class="hljs-title function_">$1</span>(');
      return { value: html };
    },
    highlightElement: function(el) {
      if (el && el.textContent) {
        el.innerHTML = this.highlightAuto(el.textContent).value;
      }
    }
  };
  global.hljs = hljs;
})(typeof window !== 'undefined' ? window : this);
